export function demoClient(data){
const root=document.getElementById('kb-recorded'),ns='http://www.w3.org/2000/svg';let mode='live';const counts=Object.fromEntries(['live','post'].map(m=>[m,root.querySelectorAll('[data-card="'+m+'"]').length]));const selected={live:Math.floor(Math.random()*counts.live),post:0};const visited={live:true,post:false};let lastWidth=0;
const names={3:'베르스타펜',16:'르클레르',44:'해밀턴',12:'안토넬리',1:'노리스',63:'러셀'};
const table=root.querySelector('#restart-table');[3,16,44,12,1,63].forEach(n=>{const s=data.restart.find(x=>x.driver_number===n);const tr=document.createElement('tr');[names[n],'SOFT',s.tyre_age_at_start+'랩 · 중고'].forEach(t=>{const td=document.createElement('td');td.textContent=t;tr.append(td)});table.append(tr)});
function el(tag,a,t){const e=document.createElementNS(ns,tag);Object.entries(a||{}).forEach(([k,v])=>e.setAttribute(k,v));if(t!==undefined)e.textContent=t;return e;}
function chart(svg){const w=svg.clientWidth;if(w<100)return;const key=svg.dataset.telemetry,h=svg.clientHeight||96,L=48,R=9,T=12,B=28,W=w-L-R,H=h-T-B;svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.replaceChildren();let series=key==='delta'?[data.delta]:data.drivers.map(d=>d.data.map(r=>[r.x,r[key]]));let flat=series.flat().map(x=>x[1]);let lo=Math.min(...flat),hi=Math.max(...flat);if(key==='brake'){lo=0;hi=1;}else if(key==='throttle'){lo=0;hi=100;}else if(key==='gear'){lo=Math.floor(lo);hi=Math.ceil(hi);}else{const pad=(hi-lo)*.07||1;lo-=pad;hi+=pad;}const x=v=>L+v/4304*W,y=v=>T+H-(v-lo)/(hi-lo)*H;
for(let i=0;i<3;i++){let v=lo+(hi-lo)*i/2;if(key==='brake'&&i===1)continue;const yy=y(v);svg.append(el('line',{x1:L,y1:yy,x2:w-R,y2:yy,class:'grid'}));svg.append(el('text',{x:L-6,y:yy+4,'text-anchor':'end'},key==='brake'?(v?'ON':'OFF'):Math.round(v)));}const ticks=w<300?[0,2000,4304]:[0,1000,2000,3000,4304];ticks.forEach(v=>svg.append(el('text',{x:x(v),y:h-13,'text-anchor':v===0?'start':v===4304?'end':'middle'},v)));svg.append(el('text',{x:w-R,y:h-1,'text-anchor':'end'},'Distance (m)'));
series.forEach((s,j)=>{let path='';s.forEach(([xx,v],i)=>{if(!i)path+='M'+x(xx)+','+y(v);else if(key==='brake'||key==='gear')path+='H'+x(xx)+'V'+y(v);else path+='L'+x(xx)+','+y(v)});svg.append(el('path',{d:path,class:'trace'+(j?' alt':'')}));});
}
function longrunChart(svg){
const w=svg.clientWidth;if(w<100)return;const h=165,L=50,R=12,T=18,B=33,W=w-L-R,H=h-T-B;
svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.replaceChildren();const values=data.longrun.flatMap(s=>s.points.filter(p=>p.y!==null).map(p=>p.y));const lo=Math.min(...values)-.15,hi=Math.max(...values)+.15;
const x=v=>L+(v-1)/11*W,y=v=>T+H-(v-lo)/(hi-lo)*H;
for(let i=0;i<3;i++){const v=lo+(hi-lo)*i/2,yy=y(v);svg.append(el('line',{x1:L,y1:yy,x2:w-R,y2:yy,class:'grid'}));svg.append(el('text',{x:L-6,y:yy+4,'text-anchor':'end'},v.toFixed(1)));}
[1,6,12].forEach(v=>svg.append(el('text',{x:x(v),y:h-16,'text-anchor':v===1?'start':v===12?'end':'middle'},v)));svg.append(el('text',{x:L,y:11},'Lap time (s)'));svg.append(el('text',{x:w-R,y:h-2,'text-anchor':'end'},'Run lap'));
data.longrun.forEach((s,j)=>{let path='',open=false;s.points.forEach(p=>{if(p.y===null){open=false;return;}path+=(open?'L':'M')+x(p.x)+','+y(p.y);open=true;const dot=el('circle',{cx:x(p.x),cy:y(p.y),r:2.5,fill:j?'var(--blue)':'var(--mint)'});dot.append(el('title',{},s.driver+' L'+p.lap+' · '+p.y.toFixed(3)+'s'));svg.append(dot);});svg.append(el('path',{d:path,class:'trace'+(j?' alt':'')}));});
}
function draw(){root.querySelectorAll('[data-telemetry]').forEach(chart);root.querySelectorAll('.longrun').forEach(longrunChart);}
function fit(){if(root.clientWidth===lastWidth)return;lastWidth=root.clientWidth;['live','post'].forEach(m=>{const sec=root.querySelector('#record-'+m),hidden=sec.hidden;sec.hidden=false;const cards=[...sec.querySelectorAll('[data-card]')],old=cards.map(c=>c.hidden);cards.forEach(c=>{c.hidden=false;c.style.height='auto';});const height=Math.ceil(Math.max(...cards.map(c=>c.getBoundingClientRect().height)))+24;cards.forEach((c,i)=>{if(matchMedia('(min-width:701px)').matches)c.style.height=height+'px';c.hidden=old[i];});sec.hidden=hidden;});}
function render(){['live','post'].forEach(m=>{root.querySelector('#record-'+m).hidden=m!==mode;root.querySelector('#record-'+m+'-tab').setAttribute('aria-selected',String(m===mode));root.querySelectorAll('[data-card="'+m+'"]').forEach((c,i)=>c.hidden=i!==selected[m]);});root.querySelector('.counter').textContent=String(selected[mode]+1).padStart(2,'0')+' / '+counts[mode]+' · '+(mode==='live'?'실시간 브리핑':'사후 분석');requestAnimationFrame(draw);}
['live','post'].forEach(m=>{root.querySelector('#record-'+m+'-tab').addEventListener('click',()=>{mode=m;if(!visited[m]){selected[m]=Math.floor(Math.random()*counts[m]);visited[m]=true;}render()});});root.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>{const m=b.dataset.nav;selected[m]=(selected[m]+(+b.dataset.dir)+counts[m])%counts[m];render()}));new ResizeObserver(()=>{fit();draw()}).observe(root);fit();render();if(document.fonts)document.fonts.ready.then(()=>{lastWidth=0;fit();draw();});

root.addEventListener('keydown',event=>{if(event.altKey||event.ctrlKey||event.metaKey)return;const tab=event.target.closest('[role=tab]');if(tab&&(event.key==='ArrowLeft'||event.key==='ArrowRight')){event.preventDefault();const other=mode==='live'?'post':'live';root.querySelector('#record-'+other+'-tab').click();root.querySelector('#record-'+other+'-tab').focus({preventScroll:true});}});

}
